//! M1-06: four TOTP field sources round-trip through a real KDBX generated by
//! the write backend, plus dual-write output verification.

use keepassity_core::kdbx::reader;
use keepassity_core::model::StringField;
use keepassity_core::totp::fields::{dual_write, read_entry, read_fields, TotpSource};
use keepassity_core::totp::{base32_decode, generate_at, TotpAlgorithm, TotpConfig, TotpEncoder};
use keepassxcr::{Credentials, Database, Entry, KdbxFile};
use std::path::{Path, PathBuf};

const PASSWORD: &str = "totp-sources";

fn work_dir() -> PathBuf {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../target/interop-tmp/totp-fields");
    std::fs::create_dir_all(&dir).expect("create work dir");
    dir
}

fn make_source_database(path: &Path) {
    let mut database = Database::new("totp-sources".into());
    let root = database.root_mut();
    let mut add = |title: &str, fields: &[(&str, &str, bool)]| {
        let mut entry = Entry::new(title.into());
        for (key, value, protected) in fields {
            entry.set_custom_field((*key).to_string(), (*value).to_string(), *protected);
        }
        root.entries_mut().push(entry);
    };
    add(
        "otp",
        &[(
            "otp",
            "otpauth://totp/Otp:alice?secret=JBSWY3DPEHPK3PXP&period=30&digits=6",
            true,
        )],
    );
    add(
        "legacy",
        &[
            ("TOTP Seed", "JBSWY3DPEHPK3PXP", false),
            ("TOTP Settings", "60;8;SHA256", false),
        ],
    );
    add(
        "timeotp",
        &[
            ("TimeOtp-Secret-Base32", "JBSWY3DPEHPK3PXP", false),
            ("TimeOtp-Length", "8", false),
            ("TimeOtp-Period", "45", false),
            ("TimeOtp-Algorithm", "HMAC-SHA-512", false),
        ],
    );
    add(
        "steam",
        &[("otp", "steam://Steam:alice?secret=JBSWY3DPEHPK3PXP", true)],
    );
    KdbxFile::new(database)
        .save(path, &Credentials::password(PASSWORD))
        .expect("save generated database");
}

fn read_source(path: &Path, title: &str) -> keepassity_core::totp::fields::TotpRead {
    let bytes = std::fs::read(path).expect("read generated database");
    let db = reader::parse(&bytes, PASSWORD).expect("parse generated database");
    let entry = db
        .root
        .entries
        .iter()
        .find(|entry| entry.field("Title") == Some(title))
        .unwrap_or_else(|| panic!("entry {title}"));
    read_entry(entry)
        .expect("read entry")
        .expect("totp present")
}

#[test]
fn four_sources_read_with_correct_priority_and_settings() {
    let path = work_dir().join("sources.kdbx");
    make_source_database(&path);

    let otp = read_source(&path, "otp");
    assert_eq!(otp.source, TotpSource::OtpUri);
    assert_eq!(otp.spec.issuer.as_deref(), Some("Otp"));
    assert_eq!(otp.spec.account.as_deref(), Some("alice"));

    let legacy = read_source(&path, "legacy");
    assert_eq!(legacy.source, TotpSource::KeepassXcLegacy);
    assert_eq!(legacy.spec.config.period, 60);
    assert_eq!(legacy.spec.config.digits, 8);
    assert_eq!(legacy.spec.config.algorithm, TotpAlgorithm::Sha256);

    let timeotp = read_source(&path, "timeotp");
    assert_eq!(timeotp.source, TotpSource::TimeOtp);
    assert_eq!(timeotp.spec.config.algorithm, TotpAlgorithm::Sha512);
    assert_eq!(timeotp.spec.config.period, 45);

    let steam = read_source(&path, "steam");
    assert_eq!(steam.source, TotpSource::OtpUri);
    assert_eq!(steam.spec.config.encoder, TotpEncoder::Steam);
    assert_eq!(steam.spec.config.output_digits(), 5);
}

#[test]
fn dual_write_is_read_back_from_kdbx() {
    let path = work_dir().join("dual-write.kdbx");
    make_source_database(&path);
    let source = read_source(&path, "otp");
    let update = dual_write(&source.spec).expect("build dual-write update");

    let credentials = Credentials::password(PASSWORD);
    let mut file = KdbxFile::open(&path, &credentials).expect("open generated");
    let entry = file
        .database
        .entry_by_path_mut(&[], "otp")
        .expect("entry otp");
    for field in &update.set {
        entry.set_custom_field(field.key.clone(), field.value.clone(), field.protected);
    }
    file.save(&path, &credentials).expect("save dual-write");

    let bytes = std::fs::read(&path).expect("read dual-write");
    let db = reader::parse(&bytes, PASSWORD).expect("parse dual-write");
    let entry = db
        .root
        .entries
        .iter()
        .find(|entry| entry.field("Title") == Some("otp"))
        .expect("entry");
    let fields: Vec<(&str, &str)> = entry
        .strings
        .iter()
        .map(|field| (field.key.as_str(), field.value.as_str()))
        .collect();
    for key in [
        "otp",
        "TimeOtp-Secret-Base32",
        "TimeOtp-Length",
        "TimeOtp-Period",
        "TimeOtp-Algorithm",
    ] {
        assert!(
            fields.iter().any(|(candidate, _)| *candidate == key),
            "{key}"
        );
    }
    assert!(entry
        .strings
        .iter()
        .find(|field| field.key == "otp")
        .is_some_and(|field| field.protected));
    let read = read_entry(entry).unwrap().unwrap();
    let code = generate_at(&read.spec.config, 1_234_567_890).unwrap().code;
    assert_eq!(code.len(), 6);
}

#[test]
fn parse_uri_keeps_issuer_and_account_with_percent_encoding() {
    let spec = keepassity_core::totp::fields::parse_uri(
        "otpauth://totp/Acme%20Inc:alice%40example.com?secret=JBSWY3DPEHPK3PXP&issuer=Acme%20Inc",
    )
    .unwrap();
    assert_eq!(spec.issuer.as_deref(), Some("Acme Inc"));
    assert_eq!(spec.account.as_deref(), Some("alice@example.com"));
    let uri = keepassity_core::totp::fields::to_uri(&spec).unwrap();
    assert!(uri.contains("Acme%20Inc"));
    assert!(uri.contains("alice%40example.com"));
}

#[test]
fn model_entry_reads_timeotp() {
    let mut entry = keepassity_core::model::Entry::default();
    entry.strings.push(StringField {
        key: "TimeOtp-Secret-Base32".into(),
        value: "JBSWY3DPEHPK3PXP".into(),
        protected: false,
        unknown: Vec::new(),
    });
    let read = read_entry(&entry).unwrap().unwrap();
    assert_eq!(read.source, TotpSource::TimeOtp);
    assert_eq!(
        read.spec.config.secret,
        base32_decode("JBSWY3DPEHPK3PXP").unwrap()
    );
    assert_eq!(
        read.spec.config,
        TotpConfig {
            secret: base32_decode("JBSWY3DPEHPK3PXP").unwrap(),
            algorithm: TotpAlgorithm::Sha1,
            digits: 6,
            period: 30,
            encoder: TotpEncoder::Totp,
        }
    );
    assert!(read_fields(&[("otp", "bad")]).is_err());
}

/// Manual interop helper: install dual-write fields into the public TOTP
/// fixture so KeePassXC / KeePassLib can be pointed at the exact bytes.
#[test]
#[ignore = "requires KEEPASSITY_TOTP_DUAL_WRITE_OUT"]
fn write_dual_write_fixture_for_interop() {
    let output =
        std::env::var("KEEPASSITY_TOTP_DUAL_WRITE_OUT").expect("KEEPASSITY_TOTP_DUAL_WRITE_OUT");
    let fixture = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/fixtures/keepass-rs/test_db_kdbx4_with_totp_entry.kdbx");
    let bytes = std::fs::read(&fixture).expect("fixture");
    let db = reader::parse(&bytes, "test").expect("read fixture");
    let entry = db
        .root
        .entries
        .iter()
        .find(|entry| entry.field("Title") == Some("this entry has totp"))
        .expect("totp entry");
    let source = read_entry(entry).unwrap().unwrap();
    let update = dual_write(&source.spec).unwrap();
    let credentials = Credentials::password("test");
    let mut file = KdbxFile::open(&fixture, &credentials).expect("open fixture");
    let target = file
        .database
        .entry_by_path_mut(&[], "this entry has totp")
        .expect("fixture entry");
    for field in &update.set {
        target.set_custom_field(field.key.clone(), field.value.clone(), field.protected);
    }
    KdbxFile::save(&file, &output, &credentials).expect("save interop output");
}
